import {getClient} from '../supabase-client.js';import {config} from '../config.js';import {rows} from './runtime-service.js';
export const chatService={async list(){return rows((await getClient()).from('conversations').select('*').order('updated_at',{ascending:false}).limit(100));},async create(userId){return rows((await getClient()).from('conversations').insert({user_id:userId,title:'Yeni söhbət'}).select().single());},async rename(id,title){return rows((await getClient()).from('conversations').update({title,updated_at:new Date().toISOString()}).eq('id',id));},async remove(id){return rows((await getClient()).from('conversations').delete().eq('id',id));},async messages(id,before){let query=(await getClient()).from('chat_messages').select('*').eq('conversation_id',id).order('created_at',{ascending:false}).limit(50);if(before)query=query.lt('created_at',before);return (await rows(query)).reverse();},async cancel(id){return rows((await getClient()).from('ai_requests').update({cancel_requested:true}).eq('id',id));},async stream(input,{signal,onEvent}){const c=await getClient();const {data:{session}}=await c.auth.getSession();if(!session)throw Error('AUTH_REQUIRED');const response=await fetch(config.supabaseUrl+'/functions/v1/ai-chat',{method:'POST',signal,headers:{Authorization:'Bearer '+session.access_token,apikey:config.publishableKey,'Content-Type':'application/json'},body:JSON.stringify(input)});if(!response.ok){let code='SERVICE_ERROR';try{code=(await response.json()).error||code;}catch{}throw Error(code);}const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';try{while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let end;while((end=buffer.indexOf('\n\n'))!==-1){const event=buffer.slice(0,end);buffer=buffer.slice(end+2);const type=event.split('\n').find(x=>x.startsWith('event:'))?.slice(6).trim();const raw=event.split('\n').find(x=>x.startsWith('data:'))?.slice(5);if(raw)onEvent(type,JSON.parse(raw));}}}finally{await reader.cancel().catch(()=>{});}}};
